package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.math.BigDecimal;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/**
 * Exercises {@link HttpPaymentGateway} against a real HTTP server standing in for the payment
 * provider, so both the outbound request shape and the handling of every documented response
 * shape (approved, declined, refused outright, malformed) are proven end to end.
 */
class HttpPaymentGatewayTest {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private HttpServer server;
    private HttpPaymentGateway gateway;
    private final AtomicReference<String> capturedRequestBody = new AtomicReference<>();
    private final AtomicReference<String> capturedRequestPath = new AtomicReference<>();
    private volatile int responseStatus;
    private volatile String responseBody;

    @BeforeEach
    void startFakeProvider() throws IOException {
        server = HttpServer.create(new InetSocketAddress("localhost", 0), 0);
        server.createContext("/v1/authorizations", exchange -> {
            capturedRequestPath.set(exchange.getRequestURI().toString());
            capturedRequestBody.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));

            byte[] bytes = responseBody == null ? new byte[0] : responseBody.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(responseStatus, bytes.length);
            try (var os = exchange.getResponseBody()) {
                os.write(bytes);
            }
        });
        server.start();

        var client = RestClient.builder().baseUrl("http://localhost:" + server.getAddress().getPort()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopFakeProvider() {
        server.stop(0);
    }

    @Test
    void sends_the_reference_amount_and_currency_as_json() throws Exception {
        responseStatus = 200;
        responseBody = "{\"status\":\"approved\"}";

        gateway.authorize("ORD-42", new Money(new BigDecimal("19.99"), "eur"));

        assertThat(capturedRequestPath.get()).isEqualTo("/v1/authorizations");
        Map<?, ?> sent = MAPPER.readValue(capturedRequestBody.get(), Map.class);
        assertThat(sent.get("reference")).isEqualTo("ORD-42");
        assertThat(new BigDecimal(sent.get("amount").toString())).isEqualByComparingTo("19.99");
        assertThat(sent.get("currency")).isEqualTo("EUR");
    }

    @Test
    void an_approved_response_is_read_back_as_approved() {
        responseStatus = 200;
        responseBody = "{\"status\":\"approved\"}";

        var outcome = gateway.authorize("ORD-1", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_200_response_with_a_declined_status_is_read_back_as_declined() {
        responseStatus = 200;
        responseBody = "{\"status\":\"declined\"}";

        var outcome = gateway.authorize("ORD-2", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_response_is_read_back_as_declined_even_without_a_body() {
        responseStatus = 402;
        responseBody = "";

        var outcome = gateway.authorize("ORD-3", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_status_body_is_treated_as_declined() {
        responseStatus = 200;
        responseBody = "{\"status\":\"unknown\"}";

        var outcome = gateway.authorize("ORD-4", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_server_error_from_the_provider_is_surfaced_as_a_failure() {
        responseStatus = 500;
        responseBody = "{\"error\":\"boom\"}";

        assertThatThrownBy(() -> gateway.authorize("ORD-5", new Money(BigDecimal.TEN, "USD")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
}

